const CACHE='insertcreator-v27-space-layout';
const ASSETS=['./','./index.html','./style.css','./app.js','./print-batch.js','./joint-fit.js','./tool-dimensions.js','./editor-cache.js','./context-menu.js','./module-footprint.js','./space-layout.js','./gridfinity-baseplate.js','./ruler-calibration.js','./capture.js','./trace.js','./auto-trace.js','./recognize.js','./recognize-worker.js','./neural.js','./neural-core.js','./neural-worker.js','./finger-grip.js','./geometry.js','./smart-layout.js','./tool-sets.js','./tool-categories.js','./photo-enhance.js','./photo-layout.js','./module-joints.js','./set-layout.js','./set-module.js','./tool-size.js','./size-labels.js','./bulk-edit.js','./module-edit.js','./smart-layout-client.js','./smart-layout-worker.js','./print-geometry.js','./preview3d.js','./view-controls.js','./fit-sheet.js','./model.js','./ui.js','./i18n.js','./units.js','./locales/en-app.js','./locales/en-capture.js','./locales/en-core.js','./catalog-ui.js','./catalog/index.js','./catalog/parametric.js','./catalog/imported.js','./catalog/sets.js','./vendor/earcut.js','./vendor/clipper.js','./fonts/dm-sans.ttf','./fonts/manrope.ttf','./icon.svg','./manifest.webmanifest','./licenses.html','./licenses-en.html','./licenses.css','./vendor/earcut.LICENSE','./vendor/clipper.LICENSE','./vendor/jsbn.LICENSE','./vendor/ort/LICENSE','./vendor/ort/ThirdPartyNotices.txt','./models/U2NET-LICENSE','./models/REMBG-LICENSE','./models/README.txt','./fonts/DM-Sans-OFL.txt','./fonts/Manrope-OFL.txt','./catalog/sources/polyhaven/LICENSE.txt','./catalog/sources/polyhaven/README.md','./catalog/sources/freecad-library/LICENSE-Assets.txt','./catalog/sources/freecad-library/README.md','./vendor/clipper.README.md'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request)));});
